        Sfx("level_up", "Niveau supérieur (8-bit)", "Jeu vidéo"), Sfx("coin", "Pièce (8-bit)", "Jeu vidéo"), Sfx("jump", "Saut (8-bit)", "Jeu vidéo"),
    )

    val musicList = listOf(
        Track("lofi", "Après-midi lo-fi", "Calme", 84, 64),
        Track("pop", "Énergie pop", "Dynamique", 120, 64),
        Track("ambient", "Aurore ambient", "Contemplatif", 70, 70),
        Track("epic", "Horizon épique", "Cinématique", 90, 64),
